# Show same common card UI but with Hublot price presentation
old='''function productCards(items,r){return items.map((x,i)=>`<article class="product-result"><div class="product-media"><button class="favorite-btn ${favorites.has(x.title+'|'+x.url)?'active':''}" data-fav="${i}" aria-label="Guardar favorito">${favorites.has(x.title+'|'+x.url)?'♥':'♡'}</button>${x.image?`<img class="product-thumb" src="${escapeHtml(x.image)}" alt="Imagen de producto" loading="lazy" referrerpolicy="no-referrer"><div class="product-placeholder hidden">▧</div>`:`<div class="product-placeholder">▧</div>`}</div><div class="product-result-info"><div class="product-store">${escapeHtml(storeLabel(r.platform))} · ${escapeHtml(x.source||'Vendedor por verificar')}</div><strong>${escapeHtml(x.title)}</strong><div class="product-price">${money(x.price,'USD')}</div><small>Precio consultado · confirma el importe final en la tienda.</small><div class="product-actions"><button class="external details-btn" data-details="${i}" type="button">Detalles ↗</button><button class="secondary compare-btn ${compareItems.has(x.title+'|'+x.url)?'active':''}" data-compare="${i}" type="button">⇄ Comparar</button><button class="primary add-result" data-add="${i}" type="button">＋ Agregar</button></div></div></article>`).join('');}'''
new='''function productCards(items,r){return items.map((x,i)=>{const isHublot=String(r.platform).toLowerCase()==='hublot';return `<article class="product-result"><div class="product-media"><button class="favorite-btn ${favorites.has(x.title+'|'+x.url)?'active':''}" data-fav="${i}" aria-label="Guardar favorito">${favorites.has(x.title+'|'+x.url)?'♥':'♡'}</button>${x.image?`<img class="product-thumb" src="${escapeHtml(x.image)}" alt="Imagen ilustrativa de reloj" loading="lazy" referrerpolicy="no-referrer"><div class="product-placeholder hidden">▧</div>`:`<div class="product-placeholder">▧</div>`}</div><div class="product-result-info"><div class="product-store">${escapeHtml(storeLabel(r.platform))} · ${escapeHtml(x.source||'Catálogo ProEshop')}</div><strong>${escapeHtml(x.title)}</strong><div class="product-price">${isHublot?`<del>${money(Number(x.price)*2,'USD')}</del> <strong>${money(x.price,'USD')}</strong>`:money(x.price,'USD')}</div><small>${isHublot?'50% de descuento simulado · no es una oferta oficial de HUBLOT':'Precio consultado · confirma el importe final en la tienda.'}</small><div class="product-actions"><button class="external details-btn" data-details="${i}" type="button">Detalles ↗</button><button class="secondary compare-btn ${compareItems.has(x.title+'|'+x.url)?'active':''}" data-compare="${i}" type="button">⇄ Comparar</button><button class="primary add-result" data-add="${i}" type="button">${isHublot?'＋ Agregar · 50% OFF':'＋ Agregar'}</button></div></div></article>`}).join('');}'''
if old not in s: raise SystemExit('productCards original not found')
s=s.replace(old,new)
# Add Hublot catalog source to same search pipeline, using the same result area and filters.
start=s.index('async function performSearch(')
end=s.index('\nfunction renderCompare()',start)
newfunc='''async function performSearch(queryOverride, platformOverride){if(platformOverride){selectedStore=String(platformOverride).toLowerCase();document.querySelectorAll('.store').forEach(x=>x.classList.toggle('active',x.dataset.store===selectedStore));}const platform=selectedStore;const query=String(queryOverride??$('query').value).trim();if(!query)return toast(platform==='hublot'?'Escribe el nombre o la colección del reloj.':'Escribe qué artículo buscas.');if(searchBusy)return;searchBusy=true;$('query').value=query;$('clearSearch').classList.remove('hidden');$('homeEmpty').classList.add('hidden');const btn=$('searchBtn');btn.disabled=true;btn.textContent='Buscando…';document.querySelectorAll('[data-search-store]').forEach(b=>{b.disabled=true;if(b.dataset.searchStore===platform)b.dataset.originalLabel=b.innerHTML,b.innerHTML='Buscando…';});$('searchResult').classList.remove('hidden');$('searchResult').innerHTML='<div class="home-empty"><div class="empty-orbit">⌕</div><strong>Buscando productos…</strong><p>Consultando resultados para '+escapeHtml(storeLabel(platform))+'.</p></div>';try{let r;if(platform==='hublot'){const q=query.toLocaleLowerCase();const catalog=HUBLOT_PRODUCTS.filter(x=>[x.name,x.collection,x.desc].some(v=>String(v||'').toLocaleLowerCase().includes(q))).map(x=>({title:x.name,price:Number(x.price)/2,image:x.img,url:'https://www.hublot.com/en-us/watches',source:'Catálogo HUBLOT · modelo ilustrativo',collection:x.collection,description:x.desc}));r={platform:'hublot',label:'HUBLOT',notice:'Resultados del catálogo local de ProEshop. Los modelos, imágenes y precios son ilustrativos; el descuento del 50% es simulado y no es una oferta oficial.',search_url:'https://www.hublot.com/en-us/watches',live_results:catalog};}else{r=await api('/api/search',{method:'POST',body:JSON.stringify({platform,query})});}lastSearch=r.live_results||[];lastSearchResponse=r;$('searchResult').innerHTML=`<div class="results-heading"><div><h3>${escapeHtml(r.label)} · Resultados</h3><p id="resultCount">${lastSearch.length} resultados para “${escapeHtml(query)}”</p></div><span class="live-dot">PRECIOS USD</span></div><p>${escapeHtml(r.notice||'Los precios pueden variar; confirma el total en la tienda.')}</p><div class="filter-row"><label>Precio mínimo<input id="minPrice" type="number" min="0" step="1" placeholder="USD 0"></label><label>Precio máximo<input id="maxPrice" type="number" min="0" step="1" placeholder="Sin límite"></label><label>Ordenar por<select id="sortResults"><option value="relevance">Relevancia</option><option value="low">Menor precio</option><option value="high">Mayor precio</option></select></label></div><div class="filter-extra"><label><input id="showImages" type="checkbox" checked> Mostrar imágenes</label><span class="view-toggle"><button type="button" class="active" data-layout="grid">▦</button><button type="button" data-layout="list">☰</button></span></div><a class="external" href="${escapeHtml(r.search_url)}" target="_blank" rel="noopener noreferrer">Abrir tienda oficial ↗</a><div id="comparePanel" class="compare-panel hidden"></div><div class="product-results"></div>${platform==='hublot'?'<p class="hint">El descuento se calcula para el carrito simulado. Imágenes y precios no representan una cotización oficial.</p>':'<details class="manual-details"><summary>＋ Agregar artículo manualmente</summary><form id="manualAdd" class="manual-form"><label>Nombre del artículo<input name="title" required maxlength="180" placeholder="Nombre como aparece en la tienda"></label><label>Precio en USD<input name="price" required type="number" min="0.01" max="10000000" step="0.01" placeholder="Ej. 49.99"></label><label>Enlace del producto<input name="url" type="url" required placeholder="https://www.walmart.com/…"></label><button class="primary full" type="submit">Agregar al carrito demo</button></form></details>'}`;const redraw=()=>renderResults(r);['minPrice','maxPrice','sortResults'].forEach(id=>$(id).addEventListener(id==='sortResults'?'change':'input',redraw));$('showImages').onchange=e=>document.querySelectorAll('.product-thumb').forEach(img=>img.classList.toggle('hidden',!e.target.checked));document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-layout]').forEach(x=>x.classList.toggle('active',x===b));$('searchResult').querySelector('.product-results')?.classList.toggle('list-layout',b.dataset.layout==='list')});if($('manualAdd'))$('manualAdd').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);await addItem({title:f.get('title'),price:f.get('price'),url:f.get('url')},selectedStore)};renderResults(r);renderCompare();$('searchResult').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){$('searchResult').innerHTML=`<div class="empty"><div>⚠</div><strong>No se pudo completar la búsqueda</strong><p>${escapeHtml(e.message)}</p><button class="secondary" id="retrySearch">Intentar de nuevo</button></div>`;$('retrySearch').onclick=()=>performSearch(query,platform);}finally{searchBusy=false;btn.disabled=false;btn.textContent='Buscar';document.querySelectorAll('[data-search-store]').forEach(b=>{b.disabled=false;if(b.dataset.originalLabel){b.innerHTML=b.dataset.originalLabel;delete b.dataset.originalLabel;}});}}'''
s=s[:start]+newfunc+s[end:]
# The catalog results are displayed at half price; send the original price to server, which applies the half-price discount once.
s=s.replace("price:String(item.price),currency:'USD',url})", "price:String(p==='hublot'?Number(item.price)*2:item.price),currency:'USD',url})")
# Keep the same card/cart flow, remove old separate panel render logic and listeners.
s=re.sub(r'\nfunction renderHublot\(\).*?\n\$\(\x27hublotFilter\x27\)\?\.addEventListener\(\x27change\x27,renderHublot\);.*?\n\$\(\x27hublotClearBtn\x27\)\?\.addEventListener\(\x27click\x27,.*?\);', '', s, flags=re.S)
s=s.replace("renderCart();renderHistory();renderHublot();", "renderCart();renderHistory();")
# Keep Hublot result links accepted in shared URL normalization and avoid falling back to Walmart.
s=s.replace("target:['target.com','www.target.com']};", "target:['target.com','www.target.com'],hublot:['hublot.com','www.hublot.com']};")
s=s.replace("}[String(platform||'').toLowerCase()]||'https://www.walmart.com/';", "}[String(platform||'').toLowerCase()]||'https://www.walmart.com/';")
# make sure the official Hublot link is used by normalize fallback
s=s.replace("target:`https://www.target.com/s?searchTerm=${q}`}[String(platform||'').toLowerCase()]", "target:`https://www.target.com/s?searchTerm=${q}`,hublot:`https://www.hublot.com/en-us/watches`}[String(platform||'').toLowerCase()]")
p.write_text(s)
